from lib import *
S = SS('n41')
steps = [
    step("默认格式是 [GIN] 时间 | 状态码 | 耗时 | 客户端 IP | 方法 路径(%#v 引号)\\n 加私有错误。耗时按量级截断:超过 1 分钟取 10 秒,超过 1 秒取 10 毫秒(1234 ms 显示 1.23s),超过 1 毫秒取 10 微秒。实测:/ok?token=SECRET&a=1 的完整查询串(含令牌)被写进了日志;/slow 睡 1234 ms 显示 1.23s;404(/nope)与 405 一样会被记录;c.Error 过的请求在日志行下面多出 Error #01: 数据库超时;中文路径按解码后的路径、用 %#v 带引号输出。", t=tl(S(1)), mark=lidx(S(1), '/ok?token=SECRET&a=1', '1.23s', 'Error #01: 数据库超时', '/nope', '/中文/path with space'), done=lidx(S(1), 'param.Latency.Truncate(time.Millisecond * 10)', '[GIN] %v |%s %3d %s|%s %8v %s| %15s |%s %-7s %s %#v'), kv=KV([['路径', '带完整查询串(令牌会泄漏)'], ['耗时', '按量级截断:1.23s、10 µs 粒度'], ['404 / 405', '也会被记录'], ['私有错误', '追加在日志行下面']], ['路径'])),
    step("耗时的起点与终点:Logger 在最前时,后面一个 sleep 50 ms 的中间件被计入(51.62 ms);Logger 放在这个慢中间件之后,50 ms 完全不在日志里(13.166 µs)。真实 HTTP 往返客户端测得 1.04 ms(含建立连接),服务端日志只记 77.709 µs——从 Logger 开始、到 c.Next() 返回为止,不含建立连接、读请求头、把响应真正发给客户端的时间。", t=tl(S(2)), mark=lidx(S(2), '51.62ms', '13.166µs', '77.709µs'), done=lidx(S(2), '真实 HTTP 往返'), b=bars([['Logger 在前(含 50 ms 中间件)', 51.62, '51.62 ms'], ['Logger 在后', 0.013, '0.013 ms'], ['真实 HTTP:客户端测得', 1.04, '1.04 ms'], ['真实 HTTP:日志记录', 0.078, '0.078 ms']], 51.62, mark=[0], done=[1, 3]), kv=KV([['起点', 'Logger 中间件开始处'], ['终点', 'c.Next() 返回'], ['不含', '建立连接、读头、把响应发出的时间']], ['终点'])),
    step("颜色:输出到 buffer(不是终端)时没有任何转义;gin.ForceConsoleColor() 之后 200 的状态码是 \\x1b[97;42m(白字绿底)、404 是 \\x1b[90;43m(黑字黄底)、方法 GET 是 \\x1b[97;44m(蓝底)、耗时 <100 ms 是 \\x1b[90;47m,每段后接 \\x1b[0m 复位;gin.DisableConsoleColor() 之后又没有颜色。写到文件或日志收集系统时要避免带转义,默认的 isatty 判断已经做到。", t=tl(S(3)), mark=lidx(S(3), 'ForceConsoleColor', '\\x1b[97;42m', '\\x1b[90;43m'), done=lidx(S(3), '默认(buffer 不是终端)', 'DisableConsoleColor'), kv=KV([['自动', '只有输出到终端才上色'], ['ForceConsoleColor', '强制 ANSI 颜色'], ['DisableConsoleColor', '强制无色']], ['自动'])),
    step("LoggerConfig:SkipPaths 里的 /health 完全不记;Skip 函数让状态 <400 的 /quiet/* 不记(404 的 /quiet/missing 仍然记);SkipQueryString 让 /api?token=SECRET&x=1 只记 /api,令牌不再进日志;自定义 Formatter 能拿到 TimeStamp、StatusCode、Latency、ClientIP、Method、Path、BodySize(404 且没写正文时是 -1)、Request(取 User-Agent)和 Keys(c.Set(\"user\") 的 alice)。4 个请求只产生了 2 行日志,这里输出的是 JSON 一行格式。", t=tl(S(4)), mark=lidx(S(4), '共 4 个请求,日志行数: 2', '"path\\":\\"/api\\"'), done=lidx(S(4), '/quiet/missing', '\\"user\\":alice'), kv=KV([['SkipPaths / Skip', '健康检查等不记日志'], ['SkipQueryString', '令牌不进日志'], ['Formatter', '拿到 Keys、BodySize、Request,自定义输出']], ['SkipQueryString'])),
    step("panic 时有没有访问日志取决于顺序:Logger 在外、Recovery 在内(gin.Default 的顺序)→ 响应 500,访问日志 1 行(500,1.47 ms);Recovery 在外、Logger 在内 → 响应仍是 500,但访问日志 0 行——panic 一路穿过 Logger(它的日志代码在 c.Next() 之后,被跳过)才被外面的 Recovery 接住。", t=tl(S(5)), mark=lidx(S(5), 'Recovery 在外、Logger 在内 → 响应状态 500,访问日志 0 行'), done=lidx(S(5), 'Logger 在外、Recovery 在内'), b=bars([['Logger 外 / Recovery 内', 1, '1 行日志'], ['Recovery 外 / Logger 内', 0, '0 行日志']], 1, done=[0], mark=[1]), kv=KV([['Logger 外', '500 的请求也有日志'], ['Recovery 外', 'panic 的请求没有访问日志'], ['结论', 'Logger 要放在 Recovery 外面']], ['结论'])),
    step("开销(空 handler,输出到 io.Discard,7 轮中位数,两轮一致):无 Logger 23 ns、0 次分配;Logger 800 ns 左右、10 次分配;自定义的空 Formatter(不拼字符串)280 ns、2 次分配——格式化那一行字符串(时间、Sprintf、%#v)占了大头。", t=tl(S(6)), mark=lidx(S(6), 'Logger(io.Discard)'), done=lidx(S(6), '无 Logger', 'Logger(空 Formatter)'), b=bars([['无 Logger', 23, '23 ns'], ['Logger(空 Formatter)', 280, '280 ns,2 allocs'], ['Logger(默认格式)', 800, '800 ns,10 allocs']], 800, done=[0, 1], mark=[2]), kv=KV([['默认 Logger', '约 800 ns / 请求,10 次分配'], ['空 Formatter', '280 ns,说明格式化占大头'], ['无 Logger', '23 ns']], ['默认 Logger'])),
]
A = mkartn('n41', 41, 'Gin,Logger,访问日志,LoggerConfig,日志格式,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 Logger 中间件:默认格式的每一段和耗时截断规则;完整查询串(含令牌)被写进日志;耗时只从 Logger 开始计到 c.Next() 返回;ForceConsoleColor 的 ANSI 转义;SkipPaths / Skip / SkipQueryString / 自定义 Formatter;Recovery 放在 Logger 外面时 panic 的请求没有访问日志;Logger 一个请求约 800 ns。',
    '[GIN] 2026/10/11 | 200 | 1.23s | 127.0.0.1 | GET "/slow" 这一行里每一段是怎么来的?耗时到底算到哪里?令牌会不会进日志?怎么改成 JSON?panic 的请求还有没有日志?这篇把 Logger 中间件的行为逐项实测,再量它自己的开销。',
    [('800 vs 23 ns', 'Logger 与无 Logger 的单请求开销(空 Formatter 为 280 ns)'), ('0 行', 'Recovery 在 Logger 外面时,panic 请求的访问日志行数'), ('SECRET', '默认日志里完整出现的查询串令牌;SkipQueryString 之后只剩路径')],
    [('一行日志的构成', '<p><code>[GIN]</code> 时间、状态码(%3d)、耗时(%8v,按量级截断)、客户端 IP(%15s)、方法(%-7s)、路径(%#v 带引号)和该请求里 Private 类型的错误。404、405 也会记录,因为 <code>Logger</code> 是全局中间件,在 404 的 handler 链里。</p>'),
     ('耗时的含义', '<p>起点是 Logger 自己开始运行,终点是 <code>c.Next()</code> 返回:Logger 之前的中间件不计入,建立连接、读取请求头、把响应字节真正送到客户端的时间也不计入。所以 Logger 要放在最外层(<code>gin.Default()</code> 就是这么放的),而且日志里的耗时不等于用户感受到的延迟。</p>'),
     ('颜色', '<p>是否上色由输出是不是终端决定(<code>isatty</code>),写到文件、buffer 时没有转义码;<code>ForceConsoleColor</code> 和 <code>DisableConsoleColor</code> 是全局开关。在容器里用 <code>docker logs</code> 看到乱码一般是因为被强制开了颜色。</p>'),
     ('配置项', '<p><code>SkipPaths</code> 精确匹配路径(健康检查),<code>Skip</code> 可以按任意条件跳过,<code>SkipQueryString</code> 避免把 API 密钥、令牌写进日志,<code>Formatter</code> 拿到完整的参数(含 <code>Keys</code>、<code>BodySize</code>、<code>Request</code>)可以输出 JSON。结构化日志需要的字段(请求 ID、用户)用 <code>c.Set</code> 存、在 Formatter 里取。</p>'),
     ('与 Recovery 的顺序', '<p>日志代码在 <code>c.Next()</code> 之后,panic 会跳过它。<code>Recovery</code> 必须放在 <code>Logger</code> 的<b>里面</b>,这样 panic 先被 Recovery 接住并写成 500,Logger 再把这个 500 记下来;反过来 panic 的请求在访问日志里会消失。</p>'),
     ('开销', '<p>默认 Logger 约 800 ns / 请求、10 次分配,相对于真实服务的毫秒级耗时可以忽略;但对每秒几十万请求的空 handler(压测、基准)来说是主要开销。大头在格式化字符串,不在计时。</p>')],
    steps,
    [ENV_N_GIN + '。日志输出到 bytes.Buffer;请求用 httptest 直接调用 ServeHTTP(客户端 IP 是 httptest 固定的 192.0.2.1),真实往返用 httptest.NewServer;开销用 testing.Benchmark 测 ServeHTTP + 丢弃输出的 writer,7 轮中位数,整个实验跑了两轮;其余每种情形各一次',
     '没有验证:输出到真实终端时 isatty 的判断;输出到文件的并发写入(Logger 没有加锁,fmt.Fprint 对 *os.File 的并发安全性未测);反向代理后 ClientIP 的取值(见后面 ClientIP 一篇);gin.DefaultWriter 的修改;结构化日志库(zap、slog)的集成'],
    'Logger 中间件')
